ProjectALife.DialogueShards["scenes_any_33"] = {
{"s9_c05_rustys_cans_003","any",2,"reg=raider|tmp=predator,seasoned|day=5,150|mood=grim",{1,"Boss shot Rusty for taking extra",2,"Rusty took two cans - two",1,"I got the cans now - Rusty's cans",2,"You eat 'em?",1,"Ate one, can't eat the other one"}},
{"s9_c05_savings_bonds_004","any",2,"reg=raider|mood=funny",{1,"Man handed over a stack of savings bonds, swore up and down they're worth a fortune",2,"When?",1,"Says right here - Matures in two thousand and three",2,"I'll put 'em in the glovebox, somebody remind me"}},
{"s9_c05_singing_treeline_005","any",2,"reg=raider|hour=1,4|mood=fear|world=trees",{1,"You hear that? Singing, out past the tree line",2,"Church folk",1,"At two in the morning?",2,"Church folk that don't sleep",1,"I ain't going out there, you go out there"}},
{"s9_c05_trailer_park_babies_006","any",2,"reg=raider|tmp=predator,seasoned|hour=16,5|mood=angry|world=road",{1,"Boss wants the trailer park by the quarry hit tonight",2,"That trailer park's got babies in it, I heard 'em from the road",1,"Boss don't care about babies",2,"I didn't say he did, I said I do",1,"Then you're gonna need to say it louder than him"}},
{"s9_c05_purse_bite_007","any",2,"reg=raider|tmp=predator|mood=funny|world=vehicle",{1,"That little old lady bit me when I grabbed her purse, hahaha! Eighty years old!",2,"She sick?",1,"Didn't look sick - looked mad - real mad",1,"Wonder how I'll look by Tuesday",2,"Truck needs gas"}},
{"s9_c05_nine_minute_light_008","any",2,"reg=outlaw|tmp=seasoned|day=5,150|hour=18,23|mood=calm|world=water",{1,"Army's got the bridges, river's the only way left",2,"Salt River runs into the Ohio at West Point, flat-bottom boat, no motor, after dark",1,"And the searchlight boat?",2,"Sweeps every nine minutes, I timed it three nights",1,"Nine minutes ain't long",2,"It's long if you row like you mean it"}},
{"s9_c05_tags_in_boot_009","any",2,"reg=outlaw|role=deserter|mood=sad",{1,"You still got your dog tags?",2,"Threw 'em in the Ohio off the Brandenburg ramp",1,"Mine are down in my boot, so somebody knows who to write to",2,"Who's gonna write?",1,"Somebody - someday - leave me that one"}},
{"s9_c05_wanted_forever_010","any",2,"reg=outlaw|tmp=seasoned|day=10,200|mood=funny",{1,"You still got those warrants on you over in Hardin County?",2,"Two of 'em",1,"Reckon they're still any good?",2,"Paper's good till somebody tears it up, ain't nobody left over there to tear it up",1,"So you're wanted forever",2,"I'm wanted, first time in my whole life anybody wanted me that bad"}},
{"s9_c05_lunchbox_name_011","any",2,"reg=outlaw|tmp=seasoned|day=3,90|hour=4,11|mood=warm|world=vehicle",{1,"Took a truck in Ekron this morning, keys were in it",2,"Where's it at?",1,"Kid's lunchbox on the seat, name on it in marker - Tanner",2,"So where's the truck?",1,"Right back where I found it - I walked"}},
{"s9_c05_street_on_arm_012","any",2,"reg=gang|day=2,90|mood=sad|world=vehicle,road",{1,"Little brother wrote our street on his arm in marker - Friday night, in the van",2,"What for?",1,"In case somebody found him and wanted to send him home",2,"It still on there?",1,"Faded, I trace it back over every night while he's sleeping"}},
{"s9_c05_fed_the_fish_013","any",2,"reg=gang|mood=funny",{1,"You ever been fishing?",2,"Rode the big riverboat downtown on a school trip, threw up over the side",1,"That's a boat ride, that ain't fishing",2,"I fed the fish, didn't I?"}},
{"s9_c05_river_be_there_014","any",2,"reg=gang|tmp=predator,seasoned|day=5,150|mood=sad|world=water",{1,"Shorty asked if Louisville's gonna be there when we go back",2,"And you told him what?",1,"Told him the river'll be there",2,"That's the truth",1,"That's why I picked it"}},
{"s9_c05_walls_no_church_015","any",2,"reg=gang|role=gang_boss,gang_member|day=3,60|hour=16,5|mood=calm|world=vehicle,building",{1,"Nine in the van and half a tank, we gotta pick somewhere tonight",2,"Somewhere with walls, somewhere with no church folks pointing rifles",1,"Walls and nobody in 'em, that's a jail, man",2,"Then drive to the jail, first time I ever asked to go"}},
{"s9_c06_mono_shirley_tab_001","any",1,"reg=club|role=biker,biker_boss|day=4,150|mood=warm|world=door",{1,"Shirley at the roadhouse kept my tab on a bar napkin under the register - since eighty-nine",1,"Napkin's still there, four hundred and twelve dollars, in her handwriting - door was busted in, but nobody took the napkin",1,"Paid it, every dollar I had on me, and a twenty on top - Shirley always did expect a tip"}},
{"s9_c06_mono_watch_the_feet_002","any",1,"reg=club|role=biker_boss|tmp=veteran|mood=grim",{1,"Man that taught me to ride said watch the other fella's front wheel - never his face",1,"Same with these things - watch the feet, the face'll lie to you",1,"Used to lie to you, now it just kinda hangs there"}},
{"s9_c06_mono_snake_bit_003","any",1,"reg=club|role=biker|day=3,120|mood=funny",{1,"Had her name put on this arm in seventy-eight, paid for it with a carburetor",1,"Covered it with a rattlesnake in eighty-four, when she left with the bass player",1,"One of 'em bit me Thursday, right on the snake, hahaha! Snakebit, wonder how the snake's feeling"}},
{"s9_c06_mono_still_riding_004","any",1,"reg=club|hour=20,2|mood=calm|world=road",{1,"Ain't talked to You since my mama's funeral, you know why",1,"Still mad about it - still riding",1,"Keep the road clear to the clubhouse tomorrow - that's all, just the road"}},
{"s9_c06_mono_six_to_five_005","any",1,"reg=crime|tmp=seasoned|hour=6,10|mood=sad",{1,"Book's open - Reds at six to five over the Cubs, if anybody's asking",1,"Nobody's betting, nobody's paying off - nobody's collecting",1,"I still write the line every morning in the book - a man needs a trade"}},
{"s9_c06_mono_barber_slips_006","any",1,"reg=crime|tmp=seasoned|day=5,150|mood=sad",{1,"Ran numbers out of the barber shop in Muldraugh fifteen years - barber cut the hair, I took the slips",1,"Barber's gone, slips still in the cigar box under the second chair",1,"Somebody played four-one-seven every day since seventy-nine, it would've hit today, nobody to pay"}},
{"s9_c06_mono_freezer_money_007","any",1,"reg=crime|sex=m|day=5,150|mood=sad",{1,"Joey, I did like you said, kept the money in the deep freeze, wrapped up like pork chops",1,"Freezer quit on the tenth - money's fine, money's always fine",1,"You'd laugh, you always said money outlives everybody - heh, you'd be real smug about it"}},
{"s9_c06_mono_honest_beans_008","any",1,"reg=crime|tmp=seasoned|mood=funny",{1,"Always told the judge I'd go straight - every time, hand on the Bible",1,"Well, Your Honor, there's nothing left worth stealing but beans",1,"So I'm stealing beans, that's practically honest work"}},
{"s9_c06_mono_white_car_009","any",1,"reg=crime|tmp=seasoned|day=3,60|mood=fear|world=vehicle,door,trees",{1,"Man we owe forty thousand is out there somewhere, saw his long white car at the rest stop",1,"Engine off, driver door open - blood all over that nice leather seat",1,"Part of me's relieved, the rest of me keeps checking the woods"}},
{"s9_c06_mono_nineteen_owe_010","any",1,"reg=crime|tmp=seasoned|day=10,200|hour=20,1|mood=sad",{1,"Loaned money in this county forty years, never once wrote a name down - kept it all in my head",1,"Lay here at night and go down the list - who owes, who I've seen walking since the ninth",1,"Eleven I ain't seen, wish I could find 'em and tell 'em it's forgiven - every dime"}},
{"s9_c06_mono_thursday_game_011","any",1,"reg=crime|tmp=seasoned|hour=19,23|mood=sad",{1,"Card game in the back of the laundromat, every Thursday for eleven years",1,"It's Thursday, dealt a hand at seven, same as always, five chairs, five hands",1,"Won every pot tonight, worst game I ever sat"}},
{"s9_c06_mono_uncle_quiet_012","any",1,"reg=crime|mood=funny",{1,"Came to this country in eighty-one, my uncle said come to Kentucky - quiet, nobody bothers you",1,"Uncle was right about the quiet",1,"He was not right about the bothering"}},
{"s9_c06_mono_cold_ravioli_013","any",1,"reg=prison|day=1,30|mood=warm",{1,"Seven years I laid on that bunk and planned the first thing I'd eat outside",1,"Ribs, from the barbecue shack on the Dixie Highway with the pig sign",1,"Shack's burned to the ground, ate a can of cold ravioli behind it - still tasted like being out"}},
{"s9_c06_mono_listening_outside_014","any",1,"reg=prison|hour=21,3|mood=calm",{1,"Chaplain always said You hear a man in a cell same as You hear him in a church",1,"Well, I ain't in the cell no more",1,"Any chance You're still listening out here?"}},
{"s9_c06_mono_long_walk_ma_015","any",1,"reg=prison|day=1,40|mood=sad|world=vehicle,fence",{1,"Ma, I'm out, not the way we talked about on the phone",1,"No parole board, no new shirt, nobody waiting in the lot with the engine running",1,"Just a hole in the fence and a long walk to Brandenburg - I'm coming anyway"}},
{"s9_c06_mono_still_in_uniform_016","any",1,"reg=prison|tmp=predator|mood=grim",{1,"Hacks used to say you'll never see the outside again - real proud of that line",1,"Well, I see it, I'm standing in it",1,"Where's the hack now? Oh, there he is, out by the tower, still in uniform"}},
{"s9_c06_mono_christmas_letters_017","any",1,"reg=prison|tmp=seasoned,predator|day=5,150|mood=sad",{1,"Wrote Mrs. Pruitt a letter every Christmas for nine years - never mailed one of 'em",1,"I'm sorry about your store, I'm sorry about Carl's arm - nine ways of saying it",1,"Walked by the store today - nobody there, left the whole stack on the counter by the register"}},
{"s9_c06_cops_ran_faster_001","any",2,"reg=club|mood=funny|world=road",{1,"Ran the Rosewood road at seventy with thirty of them strung out behind us",2,"Just like the old days",1,"Old days it was cops chasing",2,"Cops ran faster"}},
{"s9_c06_made_the_noise_002","any",2,"reg=club|day=5,150|mood=warm|world=vehicle",{1,"Little boy in the church lot asked could he sit on my bike",2,"You let him?",1,"Let him twist the throttle, engine off, key in my pocket",2,"Bet he was let down",1,"Made the engine noise himself, loudest thing in Knox County all week, nobody shushed him"}},
{"s9_c06_reflective_vest_003","any",2,"reg=club|mood=funny|world=road",{1,"My old lady's making me ride in a reflective vest - the orange road crew kind",2,"Over your colors?",1,"Over my colors, says she's not burying me on account of a dark road",2,"She's right, though",1,"Don't you dare tell her that"}},
{"s9_c06_kentucky_twice_004","any",2,"reg=club|day=7,200|mood=sad|world=fence",{1,"Gypsy's tank's got forty-one state stickers on it, she wanted all forty-eight down below",2,"Seven short",1,"Seven short, and a fence around the county",2,"Put a second Kentucky on there, she'd laugh at that"}},
{"s9_c06_vig_in_paper_005","any",2,"reg=crime|mood=funny",{1,"Sal still wants his vig on the Thursday loans",2,"Vig on what? Money's paper now",1,"So he says he'll take it in paper - toilet paper",2,"Fair, toilet paper's worth more"}},
{"s9_c06_back_room_at_nine_006","any",2,"reg=crime|tmp=seasoned|hour=20,23|mood=sad",{1,"Nicky's wife used to call the club every night at nine - asking was he coming home",2,"What'd you tell her?",1,"He's in the back room, hon, every night for six years - he never once was",2,"And now?",1,"Phone don't ring, I still say it at nine - he's in the back room, hon"}},
{"s9_c06_house_takes_aspirin_007","any",2,"reg=crime|tmp=seasoned|day=10,200|mood=funny",{1,"Sal wants the card room open again - Friday nights, back of the laundromat",2,"Who's gonna play? Nobody's got money",1,"Anybody with something to bet - shotgun shells - antibiotics, gas by the quart",2,"And the house still takes a cut?",1,"House always takes a cut, house takes it in aspirin now"}},
{"s9_c06_motel_lot_trunk_008","any",2,"reg=crime|tmp=seasoned|day=5,90|mood=grim|world=vehicle",{1,"Fella from Elizabethtown that owed Sal - Sal had me put him in the trunk Thursday night - just to scare him",2,"And?",1,"And then Friday happened, nobody went back for the car till Tuesday",2,"Jesus",1,"Car's still in the lot at the Muldraugh motel, I go the long way around that lot"}},
{"s9_c06_lemonade_cut_009","any",2,"reg=crime|day=5,120|mood=warm",{1,"Sal says we still take a cut off every business in Muldraugh - principle of the thing",2,"What business? Everything's closed",1,"Lemonade stand on Pine Street, two little girls and a card table",2,"You took a cut off a lemonade stand?",1,"They gave me a free cup, we're square with the organization"}},
{"s9_c06_went_legit_010","any",2,"reg=crime|mood=funny",{1,"We ran four thousand in twenties off the press Thursday - best batch we ever did",2,"And now?",1,"Now the real ones are worth exactly what ours are worth",2,"So we finally went legit"}},
{"s9_c06_lorraine_ledger_011","any",2,"reg=crime|tmp=seasoned|mood=sad",{1,"Lorraine did the books at the club twenty years, knew where every dollar went and who it went to",2,"She'd hate all this",1,"She'd have a ledger for it, gone, gone, gone, in that pretty handwriting of hers",2,"Ruled lines, too, she always ruled her lines"}},
{"s9_c06_safe_aint_gone_012","any",2,"reg=crime|day=5,120|mood=fear",{1,"Sal wants somebody to go up to Louisville, for the safe in the office on Preston Street",2,"Louisville's gone",1,"Safe ain't gone - Safe's two thousand pounds of steel",2,"Then Sal can go sit in it"}},
{"s9_c06_his_chessboard_013","any",2,"reg=prison|day=3,150|mood=sad|world=fence",{1,"Lamar taught me chess in the dayroom - eight years, never beat him once",2,"He make it out?",1,"Didn't make the fence, I got his board, though - cardboard one, taped at the fold",2,"Teach me, then - play me",1,"Can't, only thing I know how to do on that board is lose to Lamar"}},
{"s9_c06_didnt_know_in_014","any",2,"reg=prison|tmp=predator|mood=funny",{1,"First thing I'm doing is going to see my girl in Brandenburg",2,"She know you're out?",1,"She didn't know I was in"}},
{"s9_c06_infirmary_shots_015","any",2,"reg=prison|day=1,60|mood=sad|world=road",{1,"Officer Pierce unlocked the yard gate and told us run",2,"Pierce? Why'd Pierce do that?",1,"Said he'd rather have fifty convicts loose on the road than fifty dead men locked in his block",2,"He come with us?",1,"Went back in for the infirmary, we heard the shooting from the road, then we didn't"}},
{"s9_c06_light_left_on_016","any",2,"reg=prison|day=1,30|mood=sad",{1,"Seven years I kept a list of what I'd do my first night out",2,"What was on top?",1,"Sleep somewhere nobody tells me when the light goes off",2,"You do it?",1,"Slept in a church pew with the light on all night - could've turned it off, didn't want to"}},
{"s9_c07_mono_counting_poles_001","any",1,"reg=family|tmp=fresh,seasoned|sex=m|hour=17,22|mood=sad|world=building",{1,"Twelve poles is about a mile - near enough, hush now, bug, you're fine up there",1,"Your mama counted poles every trip we ever made to your Mamaw's in Bowling Green - out loud, drove me up the wall",1,"Forty-one - forty-two - go on back to sleep, I got the counting"}},
{"s9_c07_mono_taurus_002","any",1,"reg=civilian|tmp=seasoned|day=5,120|mood=funny|world=door",{1,"Newspaper from Friday the ninth, stuck in a screen door - Horoscopes - Taurus",1,"A surprise visit will change your plans - keep an open mind",1,"Well, can't say nobody warned me"}},
{"s9_c07_mono_hush_vacuum_003","any",1,"reg=civilian|tmp=fresh|day=1,25|mood=fear|world=building",{1,"Mr. Stamper's coat closet, mothballs and cigar smoke",1,"Three winter coats, an upright vacuum cleaner, and me, they're walking around the living room",1,"Shh - everybody hush, you too, vacuum cleaner"}},
{"s9_c07_mono_man_in_mirror_004","any",1,"reg=law|role=law_corrections|day=7,150|hour=4,11|mood=sad|world=building",{1,"Visitation is Sunday, one to four - no contact - hands stay on the table",1,"Said it to the mirror in the staff bathroom this morning - whole speech",1,"Fella in the mirror kept his hands on the table - good visit - no write-ups"}},
{"s9_c07_mono_potholes_005","any",1,"reg=worker|tmp=seasoned|day=10,200|mood=calm|world=road",{1,"Filled potholes on this stretch of road nineteen years, every spring, the same holes",1,"Nobody's filling 'em now, by next spring they'll be ditches",1,"Somebody'll cuss the county for it, I hope somebody's around to do the cussing"}},
{"s9_c07_mono_gave_him_three_006","any",1,"reg=rescue|role=rescue_medical|tmp=seasoned|mood=sad",{1,"Two aspirin, clean water, and sleep, that's what I've got to give anybody who walks in",1,"Mr. Goins asked me would it fix what's wrong with him",1,"Told him sure it would, gave him three"}},
{"s9_c07_mono_ranking_man_007","any",1,"reg=military|role=soldier_green,soldier|day=10,200|mood=funny|world=fence",{1,"Drill sergeant said I'd never amount to anything, said it to my face in front of the whole bay",1,"Well, Drill Sergeant, I'm the ranking man on this entire stretch of fence",1,"Ranking man out of one, private First Class, commanding"}},
{"s9_c07_mono_family_at_dusk_008","any",1,"reg=elite|tmp=veteran|hour=19,22|mood=warm",{1,"Family crossed the bean field at dusk - Daddy carrying the little one - Mama carrying a lamp, not lit",1,"Walked right past the hide - thirty meters, never saw us",1,"Didn't log it... didn't feel right putting it down"}},
{"s9_c07_mono_jail_or_dead_009","any",1,"reg=raider|tmp=predator|mood=funny",{1,"Mama always said I'd end up in jail or dead - every Sunday after church",1,"Well, the jail's full of them things now, and dead ain't what it used to be",1,"Beat 'em both, Mama, wish you'd lived to be wrong"}},
{"s9_c07_mono_nashville_and_back_010","any",1,"reg=club|role=biker,biker_boss|day=10,200|mood=funny",{1,"Rode to Nashville and back in one day once, eight hundred miles - couldn't feel my legs for a week",1,"Rode four miles today and called it a real good day",1,"Four miles, and I can still feel my legs, I'll take the trade"}},
{"s9_c07_mono_who_shared_011","any",1,"reg=crime|tmp=seasoned|day=15,200|mood=warm",{1,"Boss always said never write anything down, twenty years, I never did",1,"Now I write it all down - names, where they went, who was good to me",1,"If the law comes back and reads this book, they'll be real disappointed - it's mostly who shared their water"}},
{"s9_c07_mono_choir_handwriting_012","any",1,"reg=prison|day=5,150|mood=sad",{1,"Mama's church sent me a birthday card every year I was down - whole choir signed it",1,"Twelve names, I knew every one of 'em by the handwriting, miss Loretta's big loops",1,"Gonna go find that choir, see how many of those handwritings are left"}},
{"s9_c07_mono_asking_missy_013","any",1,"reg=family|role=family_youth|sex=m|day=5,90|mood=warm",{1,"Hey, Missy, would you, uh - do you maybe want to go to homecoming, with me, I mean",1,"No, hey, Missy, nobody else is asking you, so - no - that's terrible",1,"Homecoming's cancelled, stupid, still gonna ask her"}},
{"s9_c07_teeth_by_door_014","any",2,"reg=family|mood=funny|world=door",{1,"Why's Mamaw keeping her teeth in a jelly jar by the back door?",2,"Says if we have to run, she ain't leaving without her teeth",1,"That's fair",2,"Says she's also not about to bite anybody by accident"}},
{"s9_c07_taped_the_game_015","any",2,"reg=civilian|tmp=fresh,seasoned|day=3,120|mood=sad",{1,"Last thing Ronnie said to me was don't forget to set the VCR for the Reds game",2,"Did you?",1,"Taped it - Reds lost, four to one",2,"You still got the tape?",1,"Got the tape - don't have anything to play it on - don't much need to"}},
{"s9_c07_cut_back_stress_016","any",2,"reg=worker|mood=funny|world=building",{1,"Plant nurse told me in June my blood pressure was through the roof - said cut back on stress",2,"How's that coming along?",1,"Quit the job"}},
{"s9_c07_hydrant_spanner_017","any",2,"reg=rescue|role=rescue_firefighter|day=3,90|mood=sad",{1,"You alright?",2,"I'm alright - I'm alright, I just can't find the spanner",2,"The hydrant spanner - Roy kept it on his belt, and I can't, I can't find the spanner",1,"Here - use mine"}},
{"s9_c07_dog_outlasted_018","any",2,"reg=law|day=10,200|mood=funny",{1,"Remember when the department dog bit the mayor at the Fourth of July parade in eighty-seven?",2,"Mayor wanted that dog put down",1,"Sheriff said over his dead body",2,"Well, dog outlasted the sheriff and the mayor both, still on the job"}},
{"s9_c07_six_shells_019","any",2,"reg=swat|day=5,150|mood=sad",{1,"Why do you keep the shotgun shells in your shirt pocket instead of the carrier?",2,"My boy used to count 'em into my pocket before every shift - six - always six",1,"How many you got in there now?",2,"Six"}},
{"s9_c07_docs_glasses_020","any",2,"reg=military|tmp=seasoned|day=7,150|hour=20,2|mood=sad",{1,"Those are Doc's glasses, thick as a pop bottle, nobody else can see a thing through 'em",2,"I know",1,"Then why keep 'em?",2,"Put 'em on at night sometimes, whole world goes blurry - figure that's how he saw it, figure he did fine"}},
{"s9_c07_wipe_feet_sonny_021","any",2,"reg=elite|tmp=veteran|day=5,150|mood=warm|world=building",{1,"Old woman on a porch in Ekron called me sonny and told me to wipe my feet",2,"You wipe 'em?",1,"Both feet - twice, rifle on my back - then she gave me a biscuit",2,"And you took it",1,"You don't say no to a woman who calls you sonny"}},
{"s9_c07_lookout_sergeant_022","any",2,"reg=raider|mood=funny",{1,"Boss gave me a promotion",2,"To what?",1,"Lookout sergeant",2,"What's that pay?",1,"I get to sit in the shade",2,"Congratulations, I'm reporting to you now, I guess"}},
{"s9_c07_order_form_023","any",2,"reg=gang|day=5,150|mood=sad",{1,"Grandmama made me swear on her Bible I'd finish high school",2,"You was one semester off",1,"One semester, cap and gown order form's still folded up in my wallet - paid the deposit and everything",2,"What color?",1,"Maroon, she was gonna sit in the front row and holler my whole government name"}},
{"s9_c07_doll_on_handlebar_024","any",2,"reg=club|day=2,120|mood=sad|world=road",{1,"What's with the doll zip-tied to your handlebars?",2,"Granddaughter did it at Easter, so she could pick out Papaw's bike in a parking lot full of 'em",1,"Where's she at?",2,"Her mama took her across to Indiana on the eighth - doll rides with me till I can go get her"}},
{"s9_c07_real_estate_slow_025","any",2,"reg=crime|tmp=seasoned|day=5,150|mood=warm",{1,"Sal's mother still thinks he sells real estate",2,"She still alive?",1,"At her sister's place in Irvington, I walk out there every Sunday",2,"And tell her what?",1,"That the real estate market's real slow, but Sal's doing fine - she sends him back a pie"}},
{"s9_c07_learn_fast_026","any",2,"reg=prison|mood=funny|world=water",{1,"You know how to swim?",2,"Seven years inside - where exactly was I gonna swim?",1,"River's the only way out of this county",2,"Then I'm gonna learn real fast"}},
{"s9_c07_spot_by_door_027","any",2,"reg=civilian,family|tmp=fresh|day=2,30|mood=sad|world=door",{1,"You can have the loft if you want it, it's warmer up there",2,"My husband's gone, both my boys too - could I just have the spot by the door? I like to see out, if that's alright",1,"Spot by the door's yours, I'll bring you the good pillow"}},
{"s9_c07_navigate_dump_028","any",2,"reg=family|tmp=seasoned|mood=funny|world=vehicle",{1,"Squirrel for supper, your daddy reading the map, never again, my back's shot from that truck",2,"He got us here, didn't he?",1,"He got us here by way of the county dump - twice"}},
}
